const Q=`query CurrentUser { user { id address { street houseNumber city country region zipCode } email profile emailVerified profileCompleteness searchUntil } }`;
const M=`mutation SaveUser($user: PropertySearcherUserInput!) { saveUser(user:$user) { id email profile profileCompleteness } }`;
Deno.serve(async req=>{try{
 if(req.method!=='POST')return new Response('method not allowed',{status:405});
 if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});
 const b=await req.json(),uid=String(b.userId||''),action=String(b.action||'read');if(!/^[0-9a-f-]{36}$/i.test(uid))throw Error('invalid_user');
 const tok=await session(uid),read=await gql(tok,Q,{}),u=read.body?.data?.user;
 if(action==='read')return Response.json({ok:read.status===200&&!read.body?.errors,status:read.status,user:u,errors:read.body?.errors||null});
 if(action==='noop_save'){if(!u)throw Error('user_read_failed');const input={id:u.id,address:u.address,profile:u.profile};const save=await gql(tok,M,{user:input});return Response.json({ok:save.status===200&&!save.body?.errors,status:save.status,inputKeys:Object.keys(input),result:save.body});}
 if(action==='attach_test'||action==='cleanup_test'){
  if(!u)throw Error('user_read_failed');
  const marker='TECHNISCHER-TRANSFER-TEST.pdf';
  const testDoc={title:marker,name:'TECHNISCHER-TRANSFER-TEST',type:'SHARED_DOCUMENT',documentFileType:'PDF',documentType:'SHARED_DOCUMENT',identifier:'7cd4dff2affc47bca372881f809691a0',extension:'pdf',encrypted:false,url:'https://s3.eu-central-1.amazonaws.com/immomio-ps-prod-doc-storage/SHARED_DOCUMENT-7cd4dff2affc47bca372881f809691a0.pdf',bucket:'immomio-ps-prod-doc-storage',publicId:'79ba6ac2-f213-4132-b25d-3f746cd2336f'};
  const current=Array.isArray(u.profile?.attachments)?u.profile.attachments:[];
  const attachments=action==='attach_test'?[...current.filter((x:any)=>x?.title!==marker),testDoc]:current.filter((x:any)=>x?.title!==marker);
  const input={id:u.id,address:u.address,profile:{...u.profile,attachments}};
  const save=await gql(tok,M,{user:input});
  if(save.status!==200||save.body?.errors?.length)return Response.json({ok:false,status:save.status,errors:save.body?.errors||null});
  const verify=await gql(tok,Q,{}),va=verify.body?.data?.user?.profile?.attachments||[];
  return Response.json({ok:verify.status===200&&!verify.body?.errors,status:verify.status,action,testPresent:Array.isArray(va)&&va.some((x:any)=>x?.title===marker),attachmentCount:Array.isArray(va)?va.length:null});
 }
 throw Error('invalid_action');
}catch(e:any){return Response.json({ok:false,error:String(e?.message||e)},{status:400})}});

